import sys

def start():
    input_number = int(sys.stdin.read().strip())
    print(calculate(input_number))

def calculate(n):
    limit = int(4e5)
    upperPart = [0] * limit
    lowerPart = [0] * limit
    for i in range(1, limit):
        lowerPart[i] = i
        upperPart[i] = n // i
    primeMarkers = [True] * limit
    primeMarkers[0] = False
    primeMarkers[1] = False

    primeNumbers = []
    for i in range(2, limit):
        if not primeMarkers[i]:
            continue
        primeNumbers.append(i)
        for j in range(i * 2, limit, i):
            primeMarkers[j] = False

    for idx, p in enumerate(primeNumbers):
        p_sq = p * p
        for i in range(1, limit):
            if n // i < p_sq:
                break
            val = p * i
            if val < limit:
                upperPart[i] -= (upperPart[val] - (idx + 1))
            else:
                n_div_i = n // i
                lowerPart_idx = n_div_i // p
                lowerPart[lowerPart_idx] -= (lowerPart[lowerPart_idx] - (idx + 1))
        for i in range(limit - 1, p_sq - 1, -1):
            lowerPart[i] -= lowerPart[i // p] - (idx + 1)

    total = 0
    for p in primeNumbers:
        if p * p > n:
            break
        if p * p * p <= n and p * p * p > 0:
            total += 1
        if n // p > p:
            if p < limit:
                total += upperPart[p] - lowerPart[p]
            else:
                total += lowerPart[n // p] - lowerPart[p]
    return total

if __name__ == "__main__":
    start()

